// FA Remastered: gfx.h has no R16G16_SINT: a vector is kept as its two 16-bit halves in an R32UI picture (x low,
// y high), held to what 16 bits can hold (the vectors stay far within)
FfxUInt32 ffxFaPackFlow(FfxInt32x2 v)
{
    const FfxInt32x2 c = clamp(v, FfxInt32x2(-32768, -32768), FfxInt32x2(32767, 32767));
    return (FfxUInt32(c.x) & 0xffffu) | (FfxUInt32(c.y) << 16);
}
FfxInt32x2 ffxFaUnpackFlow(FfxUInt32 packed)
{
    return FfxInt32x2(FfxInt32(packed << 16) >> 16, FfxInt32(packed) >> 16);
}


